const PANOTI: S[] = [
  {
    key: 'panoti', gu: 'પનોતી', en: 'Panoti',
    whatGu: 'જન્મ રાશિ (ચંદ્ર રાશિ) પરથી શનિના ગોચર દ્વારા થતી લાંબા ગાળાની કસોટીનો સમય — મોટી (સાડાસાતી) અને નાની (ઢૈયા).', whatEn: 'A long testing period caused by Saturn’s transit relative to the natal Moon sign — the big (Sade-Sati) and small (Dhaiya) kinds.',
    howGu: 'શનિ જન્મ રાશિથી ૧૨, ૧, ૨ સ્થાને → સાડાસાતી; ૪ કે ૮ સ્થાને → ઢૈયા. શનિ એક રાશિમાં ~૨½ વર્ષ.', howEn: 'Saturn 12th, 1st or 2nd from the birth sign = Sade-Sati; 4th or 8th = Dhaiya. Saturn stays about 2½ years in a sign.',
    whyGu: 'શનિ કર્મફળ આપનાર છે; આ સમયમાં પરિશ્રમ, શિસ્ત અને ધીરજ જરૂરી. હનુમાન/શનિ ઉપાસના, દાનની પ્રથા.', whyEn: 'Saturn is the giver of karmic results; the period calls for hard work, discipline and patience. Hanuman/Shani worship and charity are customary.',
    related: ['sadesati', 'dhaiya', 'panotiphase', 'pava', 'graha:Saturn'],
  },
  { key: 'sadesati', gu: 'સાડાસાતી (મોટી પનોતી)', en: 'Sade-Sati (big panoti)', whatGu: 'શનિ જન્મ રાશિથી બારમા, પહેલા અને બીજા સ્થાને ફરે તે ૭½ વર્ષ.', whatEn: 'The 7½ years while Saturn moves through the 12th, 1st and 2nd signs from the natal Moon.', howGu: 'ત્રણ તબક્કા — દરેક ૨½ વર્ષ: માથે, છાતીએ, પગે.', howEn: 'Three phases of 2½ years each: head, chest and feet.', whyGu: 'જીવનના સંજોગો, સંબંધો અને કારકિર્દીમાં ફેરફારો અને કસોટી.', whyEn: 'Brings shifts and tests in circumstances, relationships and career.', related: ['panoti', 'panotiphase', 'pava'] },
  { key: 'dhaiya', gu: 'ઢૈયા (નાની પનોતી)', en: 'Dhaiya (small panoti)', whatGu: 'શનિ જન્મ રાશિથી ચોથા અથવા આઠમા સ્થાને હોય ત્યારે ૨½ વર્ષ.', whatEn: '2½ years while Saturn is in the 4th or 8th sign from the natal Moon.', howGu: 'શનિની ગોચર રાશિ અને જન્મ રાશિનો તફાવત ૪ અથવા ૮.', howEn: 'Saturn’s transit sign counted from the birth sign equals 4 or 8.', whyGu: 'ચોથે સુખ-ઘર, આઠમે આરોગ્ય/અવરોધ પર અસર એમ મનાય.', whyEn: 'The 4th is said to touch home and comfort, the 8th health and obstacles.', related: ['panoti', 'sadesati'] },
  { key: 'panotiphase', gu: 'પનોતીના ચરણ', en: 'Panoti phases', whatGu: 'સાડાસાતીના ત્રણ તબક્કા: ૧લું ચરણ માથે (શનિ બારમે), ૨જું છાતીએ (શનિ જન્મ રાશિમાં), ૩જું પગે (શનિ બીજે).', whatEn: 'The three phases of Sade-Sati: 1st on the head (Saturn in the 12th), 2nd on the chest (in the birth sign), 3rd on the feet (in the 2nd).', howGu: 'શનિની જન્મ રાશિથી સ્થિતિ પરથી.', howEn: 'Read from Saturn’s house relative to the birth sign.', related: ['sadesati', 'pava'] },
  { key: 'pava', gu: 'પાયો (ધાતુ)', en: 'Pava (metal)', whatGu: 'પનોતી જે ધાતુના પાયે ચાલે તે: સોનું, રૂપું, તાંબુ, લોઢું.', whatEn: 'The metal on whose “foot” the panoti is said to walk: gold, silver, copper or iron.', howGu: 'શનિ જે ઘડીએ રાશિમાં પ્રવેશે તે ક્ષણે ચંદ્ર જે રાશિમાં હોય તે, જન્મ રાશિથી ગણતાં ૧/૬/૧૧ → સોનું; ૨/૫/૯ → રૂપું; ૩/૭/૧૦ → તાંબુ; ૪/૮/૧૨ → લોઢું. જો ચંદ્ર એ ક્ષણની ±૧૨ કલાકમાં રાશિ બદલતો હોય તો ≈ ચિહ્ન (અંદાજ) દેખાય છે. આ એપ રૂપું-તાંબુ સારાં (લીલું) અને સોનું-લોઢું ભારે (લાલ) ગણે છે.', howEn: 'Take the Moon’s sign at the instant Saturn entered its current sign and count it from the birth sign: 1/6/11 → gold; 2/5/9 → silver; 3/7/10 → copper; 4/8/12 → iron. If the Moon changes sign within ±12 h of that instant the result is marked ≈ (approximate, because planet ingress times are accurate only to about a day). The app shows silver and copper as favourable (green), gold and iron as heavier (red).', whyGu: 'પનોતીનું ફળ કેટલું કઠિન કે સરળ રહેશે તેનો સંકેત.', whyEn: 'A pointer to how hard or gentle the panoti may be.', related: ['panoti', 'sadesati'] },
];

