export const STATIC_ENTRIES: GlossaryEntry[] = [
  ...mk('panchang', PANCHANG),
  ...mk('choghadiya', CHOG.filter((e) => e.key.startsWith('choghadiya'))),
  ...mk('hora', CHOG.filter((e) => e.key.startsWith('hora'))),
  ...mk('muhurat', WINDOWS.filter((e) => !['rahukaal', 'yamaganda', 'gulika'].includes(e.key))),
  ...mk('inauspicious', WINDOWS.filter((e) => ['rahukaal', 'yamaganda', 'gulika'].includes(e.key))),
  ...mk('inauspicious', FLAGS),
  ...mk('panoti', PANOTI),
  ...mk('festival', FEST.filter((e) => e.key.startsWith('festival:'))),
  ...mk('eclipse', FEST.filter((e) => ['eclipse', 'eclipse:lunar', 'eclipse:solar', 'sutak'].includes(e.key))),
  ...mk('panchang', FEST.filter((e) => ['gochar', 'dasha'].includes(e.key))),
];
// a few flags are *good* yogas, not inauspicious — recategorise
for (const e of STATIC_ENTRIES) {
  if (['raviyoga', 'amritsiddhi', 'siddhiyoga'].includes(e.key)) e.category = 'muhurat';
  if (['tithivriddhi', 'tithikshaya', 'dishashool'].includes(e.key)) e.category = 'panchang';
  if (['vyatipat', 'vaidhriti'].includes(e.key)) e.category = 'yoga';
}
